void putChar(char chr, u32int x, u32int y, u32int color) {
    char* fontPtr = psf1Font->GlyphBuffer + (chr * psf1Font->PSF1Header->CharSize);
    for (unsigned long yp = y; yp < y + 16; ++yp) {
        for (unsigned long xp = x; xp < x + 8; ++xp) {
            if ((*fontPtr & (0b10000000 >> (xp - x))) > 0) {
                putPixel(xp, yp, color);
            }
        }
        fontPtr++;
    }
}

int kmain(FRAMEBUFFER *fb, PSF1_FONT *font) {
    framebuffer = fb;
    psf1Font = font;

    for (int x = 0; x < 100; ++x) {
        for (int y = 0; y < 100; ++y) {
            putPixel(x, y, cote[y][x]);
        }
    }

    putChar(L'C', 110, 2, 0x0000ff);
    putChar(L'A', 118, 2, 0x00ff00);
    putChar(L'T', 126, 2, 0xff0000);

    for (;;) {}

    return 1;
}